package com.srent.ct01;
import com.srent.audit.AuditService; import com.srent.booking.*; import com.srent.common.ApiException; import com.srent.config.AppProperties; import com.srent.security.CurrentUser; import com.srent.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.apache.pdfbox.pdmodel.*; import org.apache.pdfbox.pdmodel.common.PDRectangle; import org.apache.pdfbox.pdmodel.font.*; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.io.*; import java.nio.file.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/ct01") @RequiredArgsConstructor
public class Ct01Controller {
    private final Ct01FormRepository forms;private final BookingRepository bookings;private final UserRepository users;private final AppProperties props;private final AuditService audit;
    public record Request(@NotNull UUID bookingId,@NotBlank @Size(max=30)String identityNumber,@NotBlank String currentAddress,@NotBlank String requestContent,String additionalData,LocalDate dateOfBirth){} public record Response(UUID id,UUID bookingId,String fullName,LocalDate dateOfBirth,String identityNumberMasked,String phone,String currentAddress,String requestedAddress,String requestContent,String additionalData,Instant createdAt,String disclaimer){static Response from(Ct01Form f){return new Response(f.getId(),f.getBooking().getId(),f.getFullName(),f.getDateOfBirth(),mask(f.getIdentityNumber()),f.getPhone(),f.getCurrentAddress(),f.getRequestedAddress(),f.getRequestContent(),f.getAdditionalData(),f.getCreatedAt(),"BẢN NHÁP - chưa phải hồ sơ được cơ quan nhà nước chấp nhận và không được tự động gửi đến cơ quan công an");}}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional public Response create(@Valid @RequestBody Request q){var b=booking(q.bookingId());var u=users.findById(CurrentUser.id()).orElseThrow();LocalDate dob=q.dateOfBirth()!=null?q.dateOfBirth():u.getDateOfBirth();if(dob==null)throw ApiException.badRequest("MISSING_DATE_OF_BIRTH","Cần ngày sinh để tạo CT01");var p=b.getRoom().getProperty();var f=new Ct01Form();f.setStudent(u);f.setBooking(b);f.setFullName(u.getFullName());f.setDateOfBirth(dob);f.setIdentityNumber(q.identityNumber());f.setPhone(u.getPhone());f.setCurrentAddress(q.currentAddress());f.setRequestedAddress(String.join(", ",p.getAddressLine(),p.getDistrict(),p.getCity()));f.setRequestContent(q.requestContent());f.setAdditionalData(q.additionalData());forms.save(f);audit.log(CurrentUser.id(),"CT01_DRAFT_CREATED","CT01",f.getId(),null);return Response.from(f);}
    @GetMapping("/my") public Page<Response> mine(@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC)Pageable p){return forms.findAllByStudentId(CurrentUser.id(),p).map(Response::from);}
    @GetMapping("/{id}") public Response one(@PathVariable UUID id){return Response.from(owned(id));}
    @PutMapping("/{id}") @Transactional public Response update(@PathVariable UUID id,@Valid @RequestBody Request q){var f=owned(id);booking(q.bookingId());f.setIdentityNumber(q.identityNumber());f.setCurrentAddress(q.currentAddress());f.setRequestContent(q.requestContent());f.setAdditionalData(q.additionalData());if(q.dateOfBirth()!=null)f.setDateOfBirth(q.dateOfBirth());return Response.from(f);}
    @GetMapping(value="/{id}/pdf",produces=MediaType.APPLICATION_PDF_VALUE) public ResponseEntity<byte[]> pdf(@PathVariable UUID id){var f=owned(id);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=CT01-draft-"+id+".pdf").body(render(f));}
    private Booking booking(UUID id){var b=bookings.findById(id).orElseThrow(()->ApiException.notFound("Booking"));if(!b.getStudent().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Booking không thuộc bạn");if(b.getStatus()!=Booking.Status.ACCEPTED&&b.getStatus()!=Booking.Status.COMPLETED)throw ApiException.conflict("BOOKING_NOT_ELIGIBLE","Booking chưa đủ điều kiện tạo CT01");return b;}private Ct01Form owned(UUID id){var f=forms.findById(id).orElseThrow(()->ApiException.notFound("CT01"));if(!f.getStudent().getId().equals(CurrentUser.id()))throw ApiException.forbidden("Tờ khai không thuộc bạn");return f;}
    private byte[] render(Ct01Form f){try(var doc=new PDDocument();var out=new ByteArrayOutputStream()){var page=new PDPage(PDRectangle.A4);doc.addPage(page);var font=PDType0Font.load(doc,fontPath().toFile());try(var cs=new PDPageContentStream(doc,page)){float y=790; y=line(cs,font,15,60,y,"BẢN NHÁP TỜ KHAI THAY ĐỔI THÔNG TIN CƯ TRÚ (CT01)");y=line(cs,font,10,60,y-12,"Chưa phải hồ sơ được cơ quan nhà nước chấp nhận");y=line(cs,font,11,60,y-24,"Họ và tên: "+f.getFullName());y=line(cs,font,11,60,y,"Ngày sinh: "+f.getDateOfBirth());y=line(cs,font,11,60,y,"Số định danh: "+f.getIdentityNumber());y=line(cs,font,11,60,y,"Số điện thoại: "+Objects.toString(f.getPhone(),""));y=wrap(cs,font,11,60,y,"Nơi ở hiện tại: "+f.getCurrentAddress());y=wrap(cs,font,11,60,y,"Địa chỉ đề nghị đăng ký: "+f.getRequestedAddress());y=wrap(cs,font,11,60,y,"Nội dung đề nghị: "+f.getRequestContent());y=wrap(cs,font,11,60,y,"Thông tin bổ sung: "+Objects.toString(f.getAdditionalData(),""));line(cs,font,9,60,y-24,"Tài liệu này chỉ là bản nháp hỗ trợ nhập liệu; S-Rent không tự động nộp hồ sơ.");}doc.save(out);return out.toByteArray();}catch(Exception e){throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,"PDF_GENERATION_FAILED","Không thể tạo PDF CT01: "+e.getMessage());}}
    private Path fontPath(){var candidates=List.of(Paths.get(props.getCt01FontPath()),Paths.get("/System/Library/Fonts/Supplemental/Arial Unicode.ttf"),Paths.get("/Library/Fonts/Arial Unicode.ttf"),Paths.get("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"));return candidates.stream().filter(Files::isRegularFile).findFirst().orElseThrow(()->new IllegalStateException("Không tìm thấy font Unicode"));}
    private float line(PDPageContentStream c,PDFont f,float size,float x,float y,String text)throws IOException{c.beginText();c.setFont(f,size);c.newLineAtOffset(x,y);c.showText(text);c.endText();return y-18;}private float wrap(PDPageContentStream c,PDFont f,float size,float x,float y,String text)throws IOException{StringBuilder l=new StringBuilder();for(String w:text.split(" ")){if(f.getStringWidth(l+" "+w)/1000*size>475){y=line(c,f,size,x,y,l.toString());l.setLength(0);}if(!l.isEmpty())l.append(' ');l.append(w);}return line(c,f,size,x,y,l.toString());}private static String mask(String s){return "*".repeat(Math.max(0,s.length()-4))+s.substring(Math.max(0,s.length()-4));}
}
